`TabResetController` stores a nonempty map of tab names to nonempty route stacks. Construction must reject malformed stacks or an unknown initial tab and defensively copy all arrays. `select(name)` must reject unknown names. Selecting a different tab changes focus without changing any stack. Selecting the already active tab resets only that tab to its first route. `snapshot()` must return defensive copies, and externally supplied or returned arrays must never alias internal arrays.

Known-bad source:
```typescript
export interface TabSnapshot {
  readonly active: string;
  readonly stacks: Readonly<Record<string, readonly string[]>>;
}

export class TabResetController {
  private active: string;
  private readonly stacks: Record<string, string[]>;

  constructor(initialTab: string, stacks: Readonly<Record<string, readonly string[]>>) {
    const names = Object.keys(stacks);
    if (names.length === 0 || !Object.prototype.hasOwnProperty.call(stacks, initialTab)) {
      throw new Error("Invalid initial tab");
    }
    this.stacks = {};
    for (const name of names) {
      if (name.trim() === "" || stacks[name].length === 0 || stacks[name].some((route) => route.trim() === "")) {
        throw new Error("Tabs and routes must be non-blank and stacks non-empty");
      }
      this.stacks[name] = [...stacks[name]];
    }
    this.active = initialTab;
  }

  select(name: string): TabSnapshot {
    if (!Object.prototype.hasOwnProperty.call(this.stacks, name)) throw new Error(`Unknown tab: ${name}`);
    if (name === this.active) {
      this.stacks[name] = this.stacks[name].slice(0, 1);
    } else {
      this.active = name;
      this.stacks[name] = this.stacks[name].slice(0, 1);
    }
    return this.snapshot();
  }

  snapshot(): TabSnapshot {
    const copy: Record<string, readonly string[]> = {};
    for (const name of Object.keys(this.stacks)) copy[name] = [...this.stacks[name]];
    return { active: this.active, stacks: copy };
  }
}
```

