import { TabResetController } from './solution';
import type { TabSnapshot } from './solution';

function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function arrayEqual(actual: readonly string[], expected: readonly string[], message: string): void {
  equal(actual.length, expected.length, `${message} length`);
  for (let i = 0; i < expected.length; i += 1) equal(actual[i], expected[i], `${message} index ${i}`);
}
function throws(action: () => unknown, message: string): void {
  let failed = false;
  try { action(); } catch (error) { failed = error instanceof Error; }
  if (!failed) throw new Error(message);
}

throws(() => new TabResetController('x', {}), 'empty map');
throws(() => new TabResetController('missing', { home: ['root'] }), 'unknown initial tab');
throws(() => new TabResetController('', { '': ['root'] }), 'blank tab name');
throws(() => new TabResetController('home', { home: [] }), 'empty stack');
throws(() => new TabResetController('home', { home: [''] }), 'empty route');
throws(() => new TabResetController('home', { home: ['  '] }), 'blank route');

const home = ['home-root', 'home-detail'];
const search = ['search-root', 'results', 'item'];
const supplied: Record<string, readonly string[]> = { home, search };
const controller = new TabResetController('home', supplied);
home.push('external');
search[0] = 'changed';
let snapshot = controller.snapshot();
equal(snapshot.active, 'home', 'initial active tab');
arrayEqual(snapshot.stacks.home, ['home-root', 'home-detail'], 'home copied');
arrayEqual(snapshot.stacks.search, ['search-root', 'results', 'item'], 'search copied');

snapshot = controller.select('search');
equal(snapshot.active, 'search', 'different tab focused');
arrayEqual(snapshot.stacks.home, ['home-root', 'home-detail'], 'old stack unchanged on focus');
arrayEqual(snapshot.stacks.search, ['search-root', 'results', 'item'], 'new stack unchanged on focus');

snapshot = controller.select('search');
equal(snapshot.active, 'search', 'same tab remains active');
arrayEqual(snapshot.stacks.search, ['search-root'], 'active tab reset to root');
arrayEqual(snapshot.stacks.home, ['home-root', 'home-detail'], 'other stack not reset');

const mutableStacks = snapshot.stacks as Record<string, string[]>;
mutableStacks.home[0] = 'mutated snapshot';
mutableStacks.search.push('mutated snapshot');
mutableStacks.extra = ['route'];
const fresh: TabSnapshot = controller.snapshot();
arrayEqual(fresh.stacks.home, ['home-root', 'home-detail'], 'snapshot route arrays defensive');
arrayEqual(fresh.stacks.search, ['search-root'], 'snapshot reset stack defensive');
equal(Object.prototype.hasOwnProperty.call(fresh.stacks, 'extra'), false, 'snapshot map defensive');
equal(fresh.stacks.home === snapshot.stacks.home, false, 'fresh arrays each snapshot');
throws(() => controller.select('unknown'), 'unknown selection');
equal(controller.snapshot().active, 'search', 'rejected selection leaves active unchanged');

